                alias_graph[name].add(alias_target)
                alias_graph[alias_target] = alias_graph.get(alias_target, set())
                alias_graph[alias_target].add(name)
    for ob in override_blocks:
        name = ob["name"]
        if "Alias" in ob["directives"]:
            for alias_target in ob["directives"]["Alias"]:
                alias_graph[name] = alias_graph.get(name, set())
