        directives = tb["directives"]
        if "Phony" in directives:
            accumulators[canonical_name]["Phony"] = directives["Phony"]  # last-one-wins
        if "Depends" in directives:
            for v in directives["Depends"]:
                accumulators[canonical_name]["Depends"].add(canonical_map[v])
        if "Before" in directives:
            for v in directives["Before"]:
                accumulators[canonical_name]["Before"].add(canonical_map[v])
        if "After" in directives:
            for v in directives["After"]:
                accumulators[canonical_name]["After"].add(canonical_map[v])
        if "Needs" in directives:
            for v in directives["Needs"]:
                accumulators[canonical_name]["Needs"].add(canonical_map[v])
        if "Requires" in directives:
            for v in directives["Requires"]:
                accumulators[canonical_name]["Requires"].add(canonical_map[v])
        # Alias is ignored for accumulation of deps

    # Process OVERRIDE blocks sorted lexicographically by id
    override_blocks_sorted = sorted(override_blocks, key=lambda ob: ob["id"])
    for ob in override_blocks_sorted:
        target_name = ob["name"]
        canonical_name = canonical_map[target_name]
        directives = ob["directives"]
        if "Phony" in directives:
            accumulators[canonical_name]["Phony"] = directives["Phony"]  # last-one-wins
        if "Depends" in directives:
            for v in directives["Depends"]:
                accumulators[canonical_name]["Depends"].add(canonical_map[v])
        if "Before" in directives:
            for v in directives["Before"]:
                accumulators[canonical_name]["Before"].add(canonical_map[v])
        if "After" in directives:
            for v in directives["After"]:
                accumulators[canonical_name]["After"].add(canonical_map[v])
        if "Needs" in directives:
            for v in directives["Needs"]:
                accumulators[canonical_name]["Needs"].add(canonical_map[v])
        if "Requires" in directives:
            for v in directives["Requires"]:
                accumulators[canonical_name]["Requires"].add(canonical_map[v])

    # Phase 5: Dependency Graph Construction
    # Graph nodes are canonical names (all_canonicals)
    graph = {cn: set() for cn in all_canonicals}  # graph[u] = set of nodes that u has edges TO

    for cn in all_canonicals:
        acc = accumulators.get(cn)
        if not acc:
            acc = {"Depends": set(), "Before": set(), "After": set(), "Needs": set(), "Requires": set()}
        deps = acc.get("Depends", set())
        before = acc.get("Before", set())
        after = acc.get("After", set())
        needs = acc.get("Needs", set())
        requires = acc.get("Requires", set())

        # Depends = X1 X2 -> edges X1 -> cn (prerequisites come before)
        for d in deps:
            graph[d].add(cn)
        # Before = Y1 Y2 -> edges cn -> Y1 (target comes before Y)
        for b in before:
            graph[cn].add(b)
        # After = Z1 Z2 -> edges Z1 -> cn (prerequisite comes before target)
        for a in after:
            graph[a].add(cn)
        # Needs = W1 W2 -> edges cn -> W1
        for n in needs:
            graph[cn].add(n)
        # Requires = V1 V2 -> edges cn -> V1
        for r in requires:
            graph[cn].add(r)

    # Phase 6: Cycle Detection - find SCCs
    # Use Tarjan's algorithm
    index_counter = [0]
    stack = []
    on_stack = {node: False for node in all_canonicals}
    index = {node: -1 for node in all_canonicals}
    lowlink = {node: -1 for node in all_canonicals}
    sccs = []  # list of lists of nodes

    def strongconnect(node):
        index[node] = lowlink[node] = index_counter[0]
        index_counter[0] += 1
        stack.append(node)
        on_stack[node] = True

        for neighbor in graph.get(node, []):
