        deps = acc.get("Depends", set())
        before = acc.get("Before", set())
        after = acc.get("After", set())
        needs = acc.get("Needs", set())
        requires = acc.get("Requires", set())

        for d in deps:
            graph[d].add(cn)
        for b in before:
            graph[cn].add(b)
        for a in after:
            graph[a].add(cn)
        for n in needs:
            graph[cn].add(n)
        for r in requires:
            graph[cn].add(r)

    # Phase 6: Cycle Detection
    index_counter = [0]
    stack = []
    on_stack = {node: False for node in all_canonicals}
    index = {node: -1 for node in all_canonicals}
    lowlink = {node: -1 for node in all_canonicals}
    sccs = []

    def strongconnect(node):
        index[node] = lowlink[node] = index_counter[0]
        index_counter[0] += 1
        stack.append(node)
        on_stack[node] = True

        for neighbor in graph.get(node, []):
            if neighbor not in index:
                strongconnect(neighbor)
                lowlink[node] = min(lowlink[node], lowlink[neighbor])
            elif on_stack.get(neighbor, False):
                lowlink[node] = min(lowlink[node], index[neighbor])

