            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == node:
                    break
            sccs.append(scc)

    for node in all_canonicals:
        if node not in index:
            strongconnect(node)

    cycles = []
    for scc in sccs:
        if len(scc) >= 2:
            cycles.append(sorted(scc))
        elif len(scc) == 1:
            node = scc[0]
            if node in graph.get(node, set()):
                cycles.append([node])
    cycles.sort()

