    comp_data = []
    for i, scc in enumerate(sccs):
        rep = min(scc)
        comp_data.append({"rep": rep, "nodes": list(scc)})

    comp_adj = {}
    for cd in comp_data:
        comp_adj[cd["rep"]] = set()

    for cd in comp_data:
        rep_a = cd["rep"]
        for u in cd["nodes"]:
            for v in graph.get(u, []):
                for other in comp_data:
                    if v in other["nodes"]:
                        rep_b = other["rep"]
                        comp_adj[rep_a].add(rep_b)
                        break

    in_degree = {cd["rep"]: 0 for cd in comp_data}
    for rep_a in comp_adj:
        for rep_b in comp_adj[rep_a]:
            in_degree[rep_b] += 1

    queue = []
    for cd in comp_data:
        rep = cd["rep"]
        if in_degree[rep] == 0:
            heapq.heappush(queue, rep)

    final_order = []
    while queue:
        rep = heapq.heappop(queue)
        nodes_in_comp = None
        for cd in comp_data:
            if cd["rep"] == rep:
                nodes_in_comp = cd["nodes"]
                break
        final_order.extend(sorted(nodes_in_comp))
        if rep in comp_adj:
            for rep_b in comp_adj[rep]:
                in_degree[rep_b] -= 1
                if in_degree[rep_b] == 0:
