                for other in comp_data:
                    if other is not cd and v in other["nodes"]:  # Only other components
                        rep_b = other["rep"]
                        comp_adj[rep_a].add(rep_b)
                        break  # Found the component for v

    in_degree = {cd["rep"]: 0 for cd in comp_data}
    for rep_a in comp_adj:
        for rep_b in comp_adj[rep_a]:
            in_degree[rep_b] += 1

    queue = []
    for cd in comp_data:
        rep = cd["rep"]
        if in_degree[rep] == 0:
            heapq.heappush(queue, rep)

    final_order = []
    while queue:
        rep = heapq.heappop(queue)
        nodes_in_comp = None
        for cd in comp_data:
            if cd["rep"] == rep:
                nodes_in_comp = cd["nodes"]
                break
        final_order.extend(sorted(nodes_in_comp))
        if rep in comp_adj:
            for rep_b in comp_adj[rep]:
                in_degree[rep_b] -= 1
                if in_degree[rep_b] == 0:
                    heapq.heappush(queue, rep_b)

    result = {"order": final_order, "cycles": cycles}
    return json.dumps(result, separators=(',', ':'))
